(197, 197, 'Desarrolla soluciones utilizando fundamentos teóricos, criterios técnicos y pensamiento crítico.', 'Sesiones teórico-prácticas, talleres y uso de recursos digitales.', 'Se consideran participación 10%, prácticas calificadas 30%, proyecto 30% y examen final 30%.', 'Bibliografía: manuales de referencia, libros de consulta y publicaciones científicas actualizadas.', '2037-07-31'),
(198, 198, 'Aplica procedimientos y buenas prácticas respetando criterios éticos y normas vigentes.', 'Aprendizaje basado en problemas, prácticas guiadas y desarrollo de proyectos.', 'Evaluación por competencias mediante ejercicios 25%, informes 25%, exposición 20% y examen 30%.', NULL, '2037-07-31'),
(199, 199, 'Comunica resultados con claridad y sustenta decisiones mediante información verificable.', 'Aprendizaje basado en problemas, prácticas guiadas y desarrollo de proyectos.', 'Evaluación continua: prácticas 30%, trabajos 20%, evaluación parcial 20% y evaluación final 30%.', 'Recursos: bibliografía del curso, repositorios académicos y documentación técnica especializada.', '2037-08-02'),
(200, 200, 'Comunica resultados con claridad y sustenta decisiones mediante información verificable.', 'Clases dialogadas, análisis de casos, resolución de ejercicios y trabajo colaborativo.', 'Evaluación por competencias mediante ejercicios 25%, informes 25%, exposición 20% y examen 30%.', 'Bibliografía básica: textos universitarios de la especialidad y artículos académicos seleccionados por el docente.', '2037-07-24');
